// Dot segments become folders: `conversation.chat.turnTail` nests under
// `conversation` > `chat`, and the final node is the selectable slot leaf.
function slotTree(names) {
  const root = { children: Object.create(null), key: '', label: '', slot: null }
  names.forEach(function (name) {
    const parts = name.split('.')
    let node = root
    let key = ''
    for (let index = 0; index < parts.length; index += 1) {
      const part = parts[index]
      key = key === '' ? part : key + '.' + part
      if (node.children[part] === undefined) {
        node.children[part] = { children: Object.create(null), key: key, label: part, slot: null }
      }
      node = node.children[part]
    }
    node.slot = name
  })
  return root
}

function groupKeys(names) {
  const keys = []
  function walk(node) {
    Object.keys(node.children).forEach(function (segment) {
      const child = node.children[segment]
      if (Object.keys(child.children).length > 0) {
        keys.push(child.key)
        walk(child)
      }
    })
  }
  walk(slotTree(names))
  return keys
}

function ancestorKeys(slotName) {
  const parts = String(slotName).split('.')
  const keys = []
  let key = ''
  for (let index = 0; index < parts.length - 1; index += 1) {
    key = key === '' ? parts[index] : key + '.' + parts[index]
    keys.push(key)
  }
  return keys
}

